        while true {
            if llfsmMachine.llfsmEntered {
                llfsmMachine.llfsmEntered = false
                if llfsmMachine.llfsmState == Crossing_State.`Go` {
                    enteredAt = llfsmCheck(now, 0, 10000, "enteredAt")
